function onInit(self, engine) {
  if (typeof self.started !== 'boolean') self.started = false;
  if (typeof self.completed !== 'boolean') self.completed = false;
  var manager = engine.uiManager || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_menu', {
    layer: 'hud',
    layerOrder: 100,
    isVisible: function() { return !self.started; },
    create: function() {
      var wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(circle at top, rgba(14,165,233,0.18), rgba(2,6,23,0.94));pointer-events:auto;font-family:Trebuchet MS,sans-serif;';
      var card = document.createElement('div');
      card.style.cssText = 'width:min(520px,92vw);padding:28px 26px;border-radius:18px;background:rgba(15,23,42,0.96);border:1px solid rgba(148,163,184,0.25);box-shadow:0 24px 80px rgba(0,0,0,0.45);color:#e2e8f0;';
      var title = document.createElement('h1');
      title.textContent = props.title || 'Koz Template';
      title.style.cssText = 'margin:0 0 8px;font-size:34px;';
      var subtitle = document.createElement('p');
      subtitle.textContent = props.subtitle || '';
      subtitle.style.cssText = 'margin:0 0 14px;color:#94a3b8;line-height:1.4;';
      var instructions = document.createElement('p');
      instructions.textContent = props.instructions || '';
      instructions.style.cssText = 'margin:0 0 18px;color:#cbd5e1;line-height:1.5;';
      var button = document.createElement('button');
      button.textContent = props.actionLabel || 'Start';
      button.style.cssText = 'padding:12px 18px;border:none;border-radius:999px;background:#38bdf8;color:#082f49;font-weight:700;cursor:pointer;';
      button.onclick = function() {
        self.started = true;
        self.completed = false;
        if (typeof self.onStartGame === 'function') self.onStartGame();
      };
      var note = document.createElement('p');
      note.textContent = props.note || '';
      note.style.cssText = 'margin:14px 0 0;color:#64748b;font-size:12px;line-height:1.5;';
      card.appendChild(title);
      if (subtitle.textContent) card.appendChild(subtitle);
      if (instructions.textContent) card.appendChild(instructions);
      card.appendChild(button);
      if (note.textContent) card.appendChild(note);
      wrap.appendChild(card);
      return wrap;
    }
  });
}

function onUpdate(self, engine, dt) {}

function resetTargets(engine) {
  var targets = engine.findObjectsByType('target');
  targets.forEach(function(target, index) {
    target.x = 110 + (index * 180);
    target.y = 130 + ((index % 2) * 110);
    target.width = 46;
    target.height = 46;
    target.baseY = target.y;
  });
}

function onInit(self, engine) {
  self.score = 0;
  self.best = 0;
  self.timeLeft = Number(props.timeLimit || 20);
  self.onStartGame = function() {
    self.score = 0;
    self.timeLeft = Number(props.timeLimit || 20);
    self.completed = false;
    resetTargets(engine);
  };

  if (window.__kozClickerPointerHandler) {
    window.removeEventListener('pointerdown', window.__kozClickerPointerHandler);
  }
  window.__kozClickerPointerHandler = function(event) {
    if (!self.started) return;
    var canvas = document.querySelector('canvas');
    if (!canvas) return;
    var rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    self.pendingClick = {
      x: (event.clientX - rect.left) * (canvas.width / rect.width),
      y: (event.clientY - rect.top) * (canvas.height / rect.height)
    };
  };
  window.addEventListener('pointerdown', window.__kozClickerPointerHandler);

  var manager = engine.uiManager || (typeof KozUIManager !== 'undefined' ? KozUIManager : null) || (typeof uiManager !== 'undefined' ? uiManager : null);
  if (!manager) return;
  manager.registerScreen(self.id + '_hud', {
    layer: 'hud',
    layerOrder: 10,
    isVisible: function() { return !!self.started; },
    create: function() {
      var panel = document.createElement('div');
      panel.style.cssText = 'position:absolute;left:16px;top:16px;padding:12px 14px;border-radius:14px;background:rgba(15,23,42,0.78);color:#e2e8f0;font-family:Trebuchet MS,sans-serif;pointer-events:none;';
      panel.innerHTML = '<div id="clickerScore" style="font-size:16px;font-weight:700;"></div><div id="clickerTime" style="margin-top:4px;font-size:12px;color:#93c5fd;"></div>';
      return panel;
    },
    update: function() {
      var score = document.getElementById('clickerScore');
      var time = document.getElementById('clickerTime');
      if (score) score.textContent = 'Score ' + self.score + ' | Best ' + self.best;
      if (time) time.textContent = 'Time left ' + self.timeLeft.toFixed(1) + 's';
    }
  });
}

function onUpdate(self, engine, dt) {
  if (!self.started) return;
  self.timeLeft = Math.max(0, self.timeLeft - dt);
  if (self.timeLeft <= 0) {
    self.best = Math.max(self.best, self.score);
    self.completed = true;
    self.started = false;
    return;
  }
  if (!self.pendingClick) return;
  var click = self.pendingClick;
  self.pendingClick = null;
  var targets = engine.findObjectsByType('target');
  for (var i = 0; i < targets.length; i += 1) {
    var target = targets[i];
    if (click.x >= target.x && click.x <= target.x + target.width && click.y >= target.y && click.y <= target.y + target.height) {
      self.score += 1;
      target.x = 70 + Math.random() * 760;
      target.y = 90 + Math.random() * 330;
      target.baseY = target.y;
      return;
    }
  }
}

function onInit(self, engine) {
  self.baseY = self.y;
  self.phase = self.x * 0.01;
}

function onUpdate(self, engine, dt) {
  var game = engine.findObject('obj_clicker_state');
  if (!game || !game.started) return;
  self.phase += dt * 3;
  self.y = self.baseY + Math.sin(self.phase) * 6;
}
